return array_map(function (array $definition, int $templateIndex): array {
    [$id, $title, $objective, $stepDefinitions] = $definition;
    $steps = [];
    foreach ($stepDefinitions as $index => [$type, $stepTitle, $expected]) {
        $steps[] = [
            'id' => sprintf('00000000-0000-4000-8000-%012d', $templateIndex * 100 + $index + 1),
            'type' => $type, 'title' => $stepTitle,
            'assigned_role' => $type === 'shared_checkpoint' ? 'both' : ($id === 'collaboration' && $index === 2 ? 'B' : 'A'),
            'url' => '', 'target' => '', 'value' => '', 'instructions' => 'نفّذ على بيانات تجريبية في البيئة المحددة، وسجّل النتيجة الفعلية.',
            'expected_result' => $expected, 'checkpoint' => $type === 'shared_checkpoint' ? $expected : '',
            'evidence_required' => false, 'depends_on' => $index ? [$steps[$index - 1]['id']] : [],
        ];
    }

    return ['id' => $id, 'name' => $title, 'content' => [
        'title' => $title, 'description' => '', 'objective' => $objective, 'priority' => 'medium', 'test_type' => 'functional',
        'prerequisites' => 'بيئة تجريبية جاهزة وحسابات مخولة.', 'required_account' => '', 'required_role' => '', 'test_data' => '',
        'expected_results' => $objective, 'acceptance_criteria' => 'تطابق جميع النتائج الفعلية النتائج المتوقعة، دون أخطاء أو تغييرات غير مصرح بها.',
        'dependencies' => [], 'status' => 'draft', 'is_template' => false, 'environment_id' => null, 'steps' => $steps,
    ]];
}, $definitions, array_keys($definitions));
